#!/usr/bin/env node
/**
 * Generates utils/generatedConfig.js from build-time environment variables,
 * and utils/generatedQr.js — the QR code of the routine builder.
 *
 * Run automatically by `npm run build` (prebuild) and `npm run preview`.
 * Direct `zeus build` calls use the last generated files.
 *
 * Resolution order for RESOLVE_BASE_URL:
 *   1. process.env.RESOLVE_BASE_URL          (CI / shell environment)
 *   2. RESOLVE_BASE_URL from ./.env          (local file, same file zeus reads)
 *   3. DEFAULT_RESOLVE_BASE_URL below       (fallback)
 *
 * Why the QR code is generated here instead of being drawn by the
 * QRCODE widget: the widget renders the code into a fixed-size bitmap and
 * crops it, so a 33-module code (this URL) loses its right-hand column —
 * the finder pattern never appears and the code cannot be scanned. The
 * matrix is generated at build time and drawn by the page itself.
 */
import fs from 'node:fs'
import path from 'node:path'
import { createRequire } from 'node:module'
import { WEB_BUILDER_PATH } from '../utils/builder.js'

// The QR encoder is a build-time dependency (devDependency "qrcode").
// The require is rooted at the package directory (npm runs the scripts
// with the package root as cwd).
const require = createRequire(process.cwd() + '/')

const DEFAULT_RESOLVE_BASE_URL = 'https://web-amcereijos-projects.vercel.app'

// npm runs scripts with the package root as cwd (zepp_app/).
const ROOT = process.cwd()
const OUT_FILE = path.join(ROOT, 'utils', 'generatedConfig.js')
const QR_FILE = path.join(ROOT, 'utils', 'generatedQr.js')
const ENV_FILE = path.join(ROOT, '.env')

function readEnvFile(file) {
  try {
    const out = {}
    for (const rawLine of fs.readFileSync(file, 'utf8').split('\n')) {
      const line = rawLine.trim()
      if (!line || line.startsWith('#')) continue
      const eq = line.indexOf('=')
      if (eq <= 0) continue
      const key = line.slice(0, eq).trim()
      let value = line.slice(eq + 1).trim()
      if (
        (value.startsWith('"') && value.endsWith('"')) ||
        (value.startsWith("'") && value.endsWith("'"))
      ) {
        value = value.slice(1, -1)
      }
      out[key] = value
    }
    return out
  } catch (e) {
    return {}
  }
}

function normalizeUrl(url) {
  return url.replace(/\/+$/, '')
}

/**
 * Writes the QR code of the routine builder as a matrix of '0'/'1' — one
 * character per module, row by row — so the watch can draw it itself.
 */
function writeQrCode(url) {
  const content = url + WEB_BUILDER_PATH
  let qr
  try {
    qr = require('qrcode').create(content, { errorCorrectionLevel: 'M' })
  } catch (e) {
    console.warn(
      '[write-config] qrcode package not available — keeping the previous QR matrix'
    )
    return
  }

  const size = qr.modules.size
  let matrix = ''
  for (let r = 0; r < size; r++) {
    for (let c = 0; c < size; c++) {
      matrix += qr.modules.get(r, c) ? '1' : '0'
    }
  }

  const contents = `// AUTO-GENERATED by scripts/write-config.js — do not edit by hand.
// Content: ${content}
export const QR_SIZE = ${size}
export const QR_MATRIX = '${matrix}'
`

  const previous = fs.existsSync(QR_FILE) ? fs.readFileSync(QR_FILE, 'utf8') : null
  if (previous !== contents) {
    fs.writeFileSync(QR_FILE, contents)
    console.log(`[write-config] QR code for ${content} (${size}x${size} modules)`)
  } else {
    console.log(`[write-config] QR code for ${content} (unchanged)`)
  }
}

function main() {
  const fromFile = readEnvFile(ENV_FILE)
  const raw =
    process.env.RESOLVE_BASE_URL ||
    fromFile.RESOLVE_BASE_URL ||
    DEFAULT_RESOLVE_BASE_URL
  const source = process.env.RESOLVE_BASE_URL
    ? 'environment'
    : fromFile.RESOLVE_BASE_URL
      ? '.env'
      : 'default'

  const url = normalizeUrl(raw.trim())

  if (!/^https?:\/\/[^\s]+$/.test(url)) {
    console.error(
      `[write-config] Invalid RESOLVE_BASE_URL: "${url}" (expected an http(s) URL)`
    )
    process.exit(1)
  }

  const contents = `// AUTO-GENERATED by scripts/write-config.js — do not edit by hand.
// Source: ${source}
export const RESOLVE_BASE_URL = '${url}'
`

  const previous = fs.existsSync(OUT_FILE) ? fs.readFileSync(OUT_FILE, 'utf8') : null
  if (previous !== contents) {
    fs.writeFileSync(OUT_FILE, contents)
    console.log(`[write-config] RESOLVE_BASE_URL = ${url} (from ${source})`)
  } else {
    console.log(`[write-config] RESOLVE_BASE_URL = ${url} (from ${source}, unchanged)`)
  }

  writeQrCode(url)
}

main()
